/**
 * CI's `paths:` filter decides whether a push runs anything at all. A path
 * missing from the list silently ships that change untested: `nix/bun.nix` is
 * regenerated by `scripts/release.ts`, so a release commit touching only it
 * pushed to `main` with no CI run (see e788bdbbfb). This test pins the
 * invariant instead of the literal list, so adding a tracked top-level source
 * directory fails here rather than in production.
 */

import { describe, expect, it } from "bun:test";
import * as fs from "node:fs";
import * as path from "node:path";

const repoRoot = path.join(import.meta.dir, "..");

type OnBlock = Record<string, { paths?: string[] }>;

function readTriggers(workflow: string): OnBlock {
	// Bun ships a YAML parser; avoid a dependency for one file.
	const parsed = Bun.YAML.parse(fs.readFileSync(path.join(repoRoot, ".github/workflows", workflow), "utf8")) as {
		on: OnBlock;
	};
	return parsed.on;
}

/** Directories whose contents CI must exercise, as a `paths:` glob. */
const REQUIRED_PATHS = [
	"packages/**",
	"crates/**",
	"scripts/**",
	"nix/**",
	"python/**",
	"sdk/**",
	"bun.lock",
	"package.json",
];

describe("CI path filters", () => {
	for (const event of ["push", "pull_request"] as const) {
		it(`runs for every build-relevant path on ${event}`, () => {
			const paths = readTriggers("ci.yml")[event]?.paths ?? [];
			expect(paths.length).toBeGreaterThan(0);
			for (const required of REQUIRED_PATHS) expect(paths).toContain(required);
			expect(new Set(paths).size).toBe(paths.length);
		});
	}

	it("keeps push and pull_request filters identical", () => {
		const triggers = readTriggers("ci.yml");
		expect([...(triggers.push?.paths ?? [])].sort()).toEqual([...(triggers.pull_request?.paths ?? [])].sort());
	});
});
